set -Eeuo pipefail
sudo -n /usr/bin/python3 - <<'PY'
import os,subprocess,time,json
from pathlib import Path
root=Path('/srv/projects/telegram-robot-leads')
old=Path('/opt/telegram-robot-leads')
config=root/'ecosystem.config.js'
recovery=root/'.pm2-canonical-migration-recovery.config.cjs'
vault=Path('/root/project-secrets/telegram-robot-leads')
data=Path('/var/lib/telegram-robot-leads')
def run(a,seconds=35):
 return subprocess.run(a,capture_output=True,text=True,timeout=seconds)
def jlist():
 r=run(['pm2','jlist'],15)
 if r.returncode:raise RuntimeError('PM2 query failed')
 return [x for x in json.loads(r.stdout) if x.get('name') in ('telegram-robot-leads','iptvpn_bot')]
def get(items,name):
 a=[x for x in items if x.get('name')==name]
 if len(a)!=1:raise RuntimeError('Expected one process named '+name)
 e=a[0].get('pm2_env') or {}
 return {'pid':a[0].get('pid'),'status':e.get('status'),'cwd':e.get('pm_cwd'),'exec':e.get('pm_exec_path'),'interpreter':e.get('exec_interpreter')}
if not root.is_dir() or root.is_symlink() or not old.is_symlink() or old.resolve()!=root:raise RuntimeError('Robot canonical root not in expected state')
if recovery.exists() or recovery.is_symlink():raise RuntimeError('Recovery file already exists; inspect first')
if not config.is_file() or config.is_symlink() or not (root/'.venv/bin/python').exists():raise RuntimeError('PM2 config or interpreter missing')
if not vault.is_dir() or vault.is_symlink() or not data.is_dir() or data.is_symlink():raise RuntimeError('Vault or state unexpectedly missing')
sessions=sorted(vault.glob('*.session'))
if len(sessions)!=2:raise RuntimeError('Session count mismatch')
session_meta={p.name:(p.stat().st_size,p.stat().st_mtime_ns,p.stat().st_ino) for p in sessions}
items0=jlist()
before=get(items0,'telegram-robot-leads')
other=get(items0,'iptvpn_bot')
if before['status']!='online' or other['status']!='online':raise RuntimeError('PM2 baseline bot offline')
if before['cwd']!=str(old) or before['exec']!=str(old/'main.py'):raise RuntimeError('Old runtime path is not the expected one')
text=config.read_text()
if '"/srv/projects/telegram-robot-leads"' not in text or str(vault) not in text or str(data) not in text:raise RuntimeError('On-disk ecosystem config mismatch')
if len([p for p in root.iterdir() if p.name==recovery.name])!=0:raise RuntimeError('Duplicate recovery file')
recovery_text=text.replace('/srv/projects/telegram-robot-leads','/opt/telegram-robot-leads')
if recovery_text==text:raise RuntimeError('Unable to create exact old-root recovery')
print('BOT_BEFORE_PID='+str(before['pid']))
print('BOT_BEFORE_CWD='+before['cwd'])
print('OTHER_BOT_PID='+str(other['pid']))
restarted=False
try:
 fd=os.open(recovery,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'w') as f:f.write(recovery_text);f.flush();os.fsync(f.fileno())
 syntax=run(['node','--check',str(config)],12)
 if syntax.returncode:raise RuntimeError('PM2 JS config syntax error')
 r=run(['pm2','startOrReload',str(config),'--only','telegram-robot-leads','--update-env'],50)
 if r.returncode:
  print('TARGETED_RELOAD_ERROR_TYPE='+r.stderr.strip()[:230])
  raise RuntimeError('Targeted PM2 restart failed')
 restarted=True
 for i in range(3):
  time.sleep(2)
  now=jlist()
  robot=get(now,'telegram-robot-leads')
  iptvpn=get(now,'iptvpn_bot')
  if robot['status']!='online' or robot['cwd']!=str(root) or robot['exec']!=str(root/'main.py'):
   if i==2:raise RuntimeError('Canonical PM2 metadata not online')
  else:break
 if iptvpn!=other:raise RuntimeError('Independent IPTV PN Bot changed')
 if len([x for x in now if x.get('name')=='telegram-robot-leads'])!=1:raise RuntimeError('Duplicate process started')
 for p in sessions:
  if (p.stat().st_size,p.stat().st_mtime_ns,p.stat().st_ino)!=session_meta[p.name]:raise RuntimeError('Telegram session changed')
 if not (data/'operation-state.json').is_file():raise RuntimeError('State file missing')
 save=run(['pm2','save'],28)
 if save.returncode:raise RuntimeError('PM2 reload succeeded but process save failed')
except Exception:
 print('TELEGRAM_CANONICAL_PM2_CUTOVER=FAILED')
 if recovery.exists() and restarted:
  restore=run(['pm2','startOrReload',str(recovery),'--only','telegram-robot-leads','--update-env'],50)
  print('PM2_ROLLBACK_COMMAND_RC='+str(restore.returncode))
  if restore.returncode==0:
   time.sleep(2)
   b=get(jlist(),'telegram-robot-leads')
   print('PM2_ROLLBACK_RUNTIME='+str(b['cwd'])+'|'+str(b['status']))
   backsave=run(['pm2','save'],25)
   print('PM2_ROLLBACK_SAVE_RC='+str(backsave.returncode))
 raise
finally:
 if recovery.exists() and recovery.is_file() and not recovery.is_symlink():recovery.unlink()
print('CANONICAL_PM2_RUNTIME_PATH='+robot['cwd'])
print('CANONICAL_PM2_SCRIPT_PATH='+robot['exec'])
print('NEW_BOT_PID='+str(robot['pid']))
print('OTHER_BOT_PID_UNCHANGED='+str(other['pid']))
print('TELEGRAM_SESSION_COUNT_PRESERVED=2')
print('TELEGRAM_STATE_FILE_PRESERVED=YES')
print('PM2_REBOOT_DUMP_SAVED=YES')
print('TELEGRAM_CANONICAL_PM2_CUTOVER=PASS')
